const eggParts=[{"material":{"doubleSided":true,"emissiveFactor":[0.0052000000562518744,0.09099999704957007,0.06824999536573895],"name":"Aurora | gleboki turkus","pbrMetallicRoughness":{"baseColorFactor":[0.00800000037997961,0.14000000059604645,0.10499999672174454,1],"metallicFactor":0.44999998807907104,"roughnessFactor":0.2800000011920929}},"position":{"offset":0,"count":4752},"normal":{"offset":19008,"count":4752},"indices":{"offset":38016,"count":9216}},{"material":{"doubleSided":true,"name":"Gold | cieple zloto","pbrMetallicRoughness":{"baseColorFactor":[0.8299999833106995,0.47999998927116394,0.11999999731779099,1],"metallicFactor":0.7799999713897705,"roughnessFactor":0.25}},"position":{"offset":74880,"count":20574},"normal":{"offset":157176,"count":20574},"indices":{"offset":239472,"count":14760}},{"material":{"doubleSided":true,"name":"Jade | turkusowa perla","pbrMetallicRoughness":{"baseColorFactor":[0.023000000044703484,0.28999999165534973,0.25,1],"metallicFactor":0.6800000071525574,"roughnessFactor":0.23999999463558197}},"position":{"offset":298512,"count":12636},"normal":{"offset":349056,"count":12636},"indices":{"offset":399600,"count":4212}}];
// A tiny self-contained sky reflection keeps the metallic Blender materials readable.
// Actual day/night light intensity is applied by the world; the shell retains its own glow.
function makeEggReflection(THREE){
 const width=64,height=32,pixels=new Uint8Array(width*height*4);
 for(let y=0;y<height;y++)for(let x=0;x<width;x++){
  const v=y/(height-1),sky=Math.max(0,(v-.4)/.6),horizon=Math.exp(-Math.pow((v-.48)/.2,2));
  const light=Math.exp(-Math.pow((x/width-.25)/.12,2)-Math.pow((v-.7)/.2,2));
  const c=[72+sky*75+horizon*105+light*80,88+sky*110+horizon*85+light*65,69+sky*148+horizon*85+light*45];
  const i=(y*width+x)*4;pixels[i]=Math.min(255,c[0]);pixels[i+1]=Math.min(255,c[1]);pixels[i+2]=Math.min(255,c[2]);pixels[i+3]=255;
 }
 const map=new THREE.DataTexture(pixels,width,height,THREE.RGBAFormat);map.colorSpace=THREE.SRGBColorSpace;map.mapping=THREE.EquirectangularReflectionMapping;map.needsUpdate=true;return map;
}

const eggCache=new WeakMap();
export function createAuroraEgg(THREE,height=3.7){
 let parts=eggCache.get(THREE);
 if(!parts){
  const raw=Uint8Array.from(atob(eggData),c=>c.charCodeAt(0)).buffer;
  const reflection=makeEggReflection(THREE);
  parts=eggParts.map(p=>{
   const geometry=new THREE.BufferGeometry();
   geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(raw,p.position.offset,p.position.count),3));
   geometry.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(raw,p.normal.offset,p.normal.count),3));
   geometry.setIndex(new THREE.BufferAttribute(new Uint32Array(raw,p.indices.offset,p.indices.count),1));
   geometry.computeBoundingSphere();
   const f=p.material.pbrMetallicRoughness;
   const material=new THREE.MeshStandardMaterial({name:p.material.name,metalness:f.metallicFactor,roughness:f.roughnessFactor,side:p.material.doubleSided?THREE.DoubleSide:THREE.FrontSide});
   material.envMap=reflection;material.envMapIntensity=1.3;
   material.color.fromArray(f.baseColorFactor);
   if(p.material.emissiveFactor)material.emissive.fromArray(p.material.emissiveFactor);
   return {geometry,material};
  });eggCache.set(THREE,parts);
 }
 const group=new THREE.Group();group.name='Jajo Zorzy';group.userData.model='blender-aurora-egg';
 group.scale.setScalar(height/3.845736503601074);
 for(const p of parts){const mesh=new THREE.Mesh(p.geometry,p.material);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);}
 return group;
}
